sealed class RenameCommand : ShellSyntaxRewriter
{
    public override SyntaxNode? VisitCommand(ShellCommandSyntax node)
        => node.NameValue == "ls" ? node.WithName("dir") : base.VisitCommand(node);
}

sealed class Counter : ShellSyntaxWalker
{
    public int Count { get; private set; }
    public override void VisitCommand(ShellCommandSyntax node) { Count++; base.VisitCommand(node); }
}

private sealed class CommandCounter : ShellSyntaxWalker
{
    public int Count { get; private set; }
    public override void VisitCommand(ShellCommandSyntax node) { Count++; base.VisitCommand(node); }
}

if (node.Kind() == SyntaxKind.Command)
{
    // handle a simple command
}
